window.KDATA.SAY={korong:['Shufflepuck: challenge us!','Shufflepuck : défie-nous !'],chess:['Fairy chess against the Fauna.','Tente ces échecs alternatifs, tiens.'],erratik:['Find the pairs.','Trouve les clones.'],faunarratik:['Your own story with us. Build!','Picore, ci et là : construis l’histoire à plusieurs.'],katabatik:['Roll for a mini-game.','Jette le dé, joue à des mini-jeux.'],'3615':['Surf the MiniTale, earn Koins.','Consulte ce bon vieux MiniTale. Chope des Koins !'],vhs:['Your own YouTube tapes.','Visionne tes programmes YouTube.'],fotofauna:['Shoot and edit.','Prends tes photos, retouche-les dans la foulée.'],faunator:['Browse .onion sites.','Tomates, salade, .onion !'],skopo:['Watch us.','Tu nous vois ?'],reporhogo:['Find any repo on anything.','Toutes les ressources "code" sur… tout.'],invaders:['Factualists want to liquefy you!','Les Divisionistes le font par zéro !'],musik:['Touched by a muse?','Touched by a muse?']};
